export const REFERENCE_SCHEMA: string = "# GraphQL Cascade Base Schema\n#\n# The normative definition of the core types and interfaces that all\n# Cascade-compliant GraphQL schemas must implement. Specification chapters\n# show excerpts; `node scripts/check-spec.mjs` checks they match this file.\n# Implementers add these types to their own schema, which provides the\n# Query root.\n\n\"\"\"\nMarks a mutation as Cascade-compliant and configures cascade behavior.\n\"\"\"\ndirective @cascade(\n  \"\"\"Maximum relationship depth to cascade through.\"\"\"\n  maxDepth: Int = 3\n\n  \"\"\"Whether to include related entities in the cascade.\"\"\"\n  includeRelated: Boolean = true\n\n  \"\"\"\n  Whether to automatically compute invalidation hints.\n  If false, server must manually specify invalidations.\n  \"\"\"\n  autoInvalidate: Boolean = true\n\n  \"\"\"\n  Entity types to exclude from cascade (e.g., don't cascade to audit logs).\n  \"\"\"\n  excludeTypes: [String!]\n) on FIELD_DEFINITION\n\n\"\"\"\nMarks a field as triggering cascade invalidation when this field changes.\n\"\"\"\ndirective @cascadeInvalidates(\n  \"\"\"Queries to invalidate when this field changes.\"\"\"\n  queries: [String!]!\n\n  \"\"\"Invalidation strategy to use.\"\"\"\n  strategy: InvalidationStrategy = INVALIDATE\n) on FIELD_DEFINITION\n\n\"\"\"\nAn object with an ID, following GraphQL Global Object Identification (the\nRelay Node interface). All domain entities MUST implement this interface.\n\"\"\"\ninterface Node {\n  \"\"\"\n  Identifier of this entity. SHOULD be unique across all types (MUST from\n  2.0.0): a UUID, or an encoded \"Type:key\".\n  \"\"\"\n  id: ID!\n}\n\n\"\"\"\nTimestamped entities for version tracking.\n\"\"\"\ninterface Timestamped {\n  createdAt: DateTime!\n  updatedAt: DateTime!\n  version: Int  # Optional: for optimistic concurrency control\n}\n\n\"\"\"\nStandard GraphQL Cascade mutation response.\nCascade mutations return this interface, or a result union (CascadePayload).\nPayload types SHOULD also expose the mutation's primary result as a `data`\nfield of its own type, e.g. `data: User`; the interface leaves `data` out\nbecause GraphQL cannot express \"any result type\" as a field type.\n\"\"\"\ninterface CascadeResponse {\n  \"\"\"Whether the mutation succeeded.\"\"\"\n  success: Boolean!\n\n  \"\"\"List of errors if mutation failed or partially succeeded.\"\"\"\n  errors: [CascadeError!]\n\n  \"\"\"The cascade of updates triggered by this mutation.\"\"\"\n  cascade: CascadeUpdates!\n}\n\n\"\"\"\nImplemented by the success member of a mutation result union\n(`<Mutation>Result = <Mutation>Payload | CascadeFailure`), the alternative to\nCascadeResponse. Payloads SHOULD also expose their result as a typed `data`.\n\"\"\"\ninterface CascadePayload {\n  \"\"\"The cascade of updates triggered by this mutation.\"\"\"\n  cascade: CascadeUpdates!\n\n  \"\"\"Non-critical problems of a mutation that succeeded (partial success).\"\"\"\n  warnings: [CascadeError!]!\n}\n\n\"\"\"\nThe failure member of a mutation result union: the mutation committed no\nchange, so there is no cascade.\n\"\"\"\ntype CascadeFailure {\n  \"\"\"Why the mutation failed; at least one.\"\"\"\n  errors: [CascadeError!]!\n}\n\n\"\"\"\nThe cascade of updates triggered by a mutation.\n\"\"\"\ntype CascadeUpdates {\n  \"\"\"All entities updated by this mutation (including the primary result).\"\"\"\n  updated: [UpdatedEntity!]!\n\n  \"\"\"All entities deleted by this mutation.\"\"\"\n  deleted: [DeletedEntity!]!\n\n  \"\"\"Query invalidation hints for cache management.\"\"\"\n  invalidations: [QueryInvalidation!]!\n\n  \"\"\"\n  Types whose affected entities are not listed individually.\n  Clients treat every cached entity of each type, and every cached\n  query that may contain one, as stale.\n  \"\"\"\n  typeInvalidations: [TypeInvalidation!]!\n\n  \"\"\"Metadata about the cascade.\"\"\"\n  metadata: CascadeMetadata!\n}\n\n\"\"\"\nMetadata about a cascade operation.\n\"\"\"\ntype CascadeMetadata {\n  \"\"\"Server timestamp when mutation executed.\"\"\"\n  timestamp: DateTime!\n\n  \"\"\"Transaction ID for tracking (optional).\"\"\"\n  transactionId: ID\n\n  \"\"\"Maximum relationship depth traversed.\"\"\"\n  depth: Int!\n\n  \"\"\"\n  Total number of entities affected, including those covered by\n  type invalidations.\n  \"\"\"\n  affectedCount: Int!\n\n  \"\"\"\n  Whether limits forced entities or invalidation hints out of this\n  response. Everything omitted is covered by typeInvalidations.\n  \"\"\"\n  truncated: Boolean!\n}\n\n\"\"\"\nEvery cached entity of this type, and every cached query that may\ncontain one, is stale.\n\"\"\"\ntype TypeInvalidation {\n  \"\"\"GraphQL type name, e.g. \"Post\".\"\"\"\n  typename: String!\n\n  \"\"\"Number of affected entities of this type, when known.\"\"\"\n  affectedCount: Int\n}\n\n\"\"\"\nAn entity that was updated in the cascade.\n\"\"\"\ntype UpdatedEntity {\n  \"\"\"\n  Type name of the entity (e.g., \"User\", \"Company\").\n  Replaces the deprecated `__typename` pseudo-field.\n  \"\"\"\n  typename: String!\n\n  \"\"\"ID of the entity.\"\"\"\n  id: ID!\n\n  \"\"\"The operation performed.\"\"\"\n  operation: CascadeOperation!\n\n  \"\"\"The full entity data.\"\"\"\n  entity: Node!\n\n  \"\"\"\n  Fields whose values the update changed. Null when the server does not know,\n  and for created entities, whose fields are all new.\n  \"\"\"\n  updatedFields: [String!]\n}\n\n\"\"\"\nAn entity that was deleted in the cascade.\n\"\"\"\ntype DeletedEntity {\n  \"\"\"\n  Type name of the deleted entity.\n  Replaces the deprecated `__typename` pseudo-field.\n  \"\"\"\n  typename: String!\n\n  \"\"\"ID of the deleted entity.\"\"\"\n  id: ID!\n\n  \"\"\"When the entity was deleted.\"\"\"\n  deletedAt: DateTime!\n}\n\n\"\"\"\nType of cascade operation.\n\"\"\"\nenum CascadeOperation {\n  CREATED\n  UPDATED\n  DELETED\n}\n\n\"\"\"\nInstructions for cache invalidation after a mutation.\n\"\"\"\ntype QueryInvalidation {\n  \"\"\"\n  Query name to invalidate (e.g., \"listUsers\", \"getCompany\").\n  If null, use queryPattern.\n  \"\"\"\n  queryName: String\n\n  \"\"\"\n  Hash of the query for exact matching.\n  \"\"\"\n  queryHash: String\n\n  \"\"\"\n  Arguments that identify the query to invalidate.\n  Example: { \"companyId\": \"123\" }\n  \"\"\"\n  arguments: JSON\n\n  \"\"\"\n  Pattern to match queries (e.g., \"list*\", \"get*\").\n  \"\"\"\n  queryPattern: String\n\n  \"\"\"\n  Strategy for handling the invalidation.\n  \"\"\"\n  strategy: InvalidationStrategy!\n\n  \"\"\"\n  Scope of the invalidation.\n  \"\"\"\n  scope: InvalidationScope!\n}\n\n\"\"\"\nStrategy for cache invalidation.\n\"\"\"\nenum InvalidationStrategy {\n  \"\"\"Mark the query as stale, refetch on next access.\"\"\"\n  INVALIDATE\n\n  \"\"\"Immediately refetch the query.\"\"\"\n  REFETCH\n\n  \"\"\"Remove the query from cache entirely.\"\"\"\n  REMOVE\n}\n\n\"\"\"\nScope of cache invalidation.\n\"\"\"\nenum InvalidationScope {\n  \"\"\"Only invalidate the exact query with exact arguments.\"\"\"\n  EXACT\n\n  \"\"\"Invalidate all queries with names matching the prefix.\"\"\"\n  PREFIX\n\n  \"\"\"Invalidate all queries matching the pattern (glob-style).\"\"\"\n  PATTERN\n\n  \"\"\"Invalidate all queries.\"\"\"\n  ALL\n}\n\n\"\"\"\nError in a cascade mutation.\n\"\"\"\ntype CascadeError {\n  \"\"\"Human-readable error message.\"\"\"\n  message: String!\n\n  \"\"\"Machine-readable error category. Drives generic client handling.\"\"\"\n  code: CascadeErrorCode!\n\n  \"\"\"\n  Application-defined code identifying the specific condition,\n  e.g. \"INSUFFICIENT_FUNDS\". Refines `code`; never replaces it.\n  \"\"\"\n  domainCode: String\n\n  \"\"\"Field that caused the error (if applicable).\"\"\"\n  field: String\n\n  \"\"\"Path to the error in the input.\"\"\"\n  path: [String!]\n\n  \"\"\"Additional error metadata.\"\"\"\n  extensions: JSON\n}\n\n\"\"\"\nStandard error codes for Cascade mutations.\n\"\"\"\nenum CascadeErrorCode {\n  \"\"\"Input validation failed.\"\"\"\n  VALIDATION_ERROR\n\n  \"\"\"Entity not found.\"\"\"\n  NOT_FOUND\n\n  \"\"\"User not authenticated.\"\"\"\n  UNAUTHORIZED\n\n  \"\"\"User lacks permission.\"\"\"\n  FORBIDDEN\n\n  \"\"\"Version conflict or unique constraint violation.\"\"\"\n  CONFLICT\n\n  \"\"\"Server error.\"\"\"\n  INTERNAL_ERROR\n\n  \"\"\"Database transaction failed.\"\"\"\n  TRANSACTION_FAILED\n\n  \"\"\"Operation timed out.\"\"\"\n  TIMEOUT\n\n  \"\"\"Rate limit exceeded.\"\"\"\n  RATE_LIMITED\n\n  \"\"\"Service temporarily unavailable.\"\"\"\n  SERVICE_UNAVAILABLE\n}\n\n\"\"\"\nSubscription for real-time cascade updates.\n\"\"\"\ntype Subscription {\n  \"\"\"\n  Subscribe to cascade updates for specific entity types.\n  \"\"\"\n  cascadeUpdates(\n    \"\"\"Entity types to subscribe to (e.g., [\"User\", \"Company\"]).\"\"\"\n    entityTypes: [String!]\n\n    \"\"\"Optional filter by entity IDs.\"\"\"\n    entityIds: [ID!]\n\n    \"\"\"Optional filter by operations.\"\"\"\n    operations: [CascadeOperation!]\n  ): CascadeUpdateEvent!\n}\n\n\"\"\"\nReal-time cascade update event.\n\"\"\"\ntype CascadeUpdateEvent {\n  \"\"\"Type of event.\"\"\"\n  eventType: CascadeEventType!\n\n  \"\"\"The updated entity (for CREATED/UPDATED events).\"\"\"\n  entity: UpdatedEntity\n\n  \"\"\"The deleted entity (for DELETED events).\"\"\"\n  deletedEntity: DeletedEntity\n\n  \"\"\"Timestamp of the event.\"\"\"\n  timestamp: DateTime!\n\n  \"\"\"Transaction that caused this update.\"\"\"\n  transactionId: ID\n\n  \"\"\"Source of the event.\"\"\"\n  source: EventSource!\n}\n\n\"\"\"\nType of cascade event.\n\"\"\"\nenum CascadeEventType {\n  ENTITY_CREATED\n  ENTITY_UPDATED\n  ENTITY_DELETED\n}\n\n\"\"\"\nSource of the cascade event.\n\"\"\"\nenum EventSource {\n  MUTATION     # Event from a mutation\n  SUBSCRIPTION # Event from another subscription\n  SYSTEM       # System-generated event\n}\n\n\"\"\"\nCascade capabilities of a server, for version discovery. Servers expose it\nas a `cascadeInfo: CascadeInfo!` field on their Query type.\n\"\"\"\ntype CascadeInfo {\n  \"\"\"Specification version the server implements, e.g. \"1.5.0\".\"\"\"\n  version: String!\n\n  \"\"\"Specification versions whose responses the server can produce.\"\"\"\n  supportedVersions: [String!]!\n\n  \"\"\"Experimental features the server has enabled.\"\"\"\n  experimentalFeatures: [String!]!\n\n  \"\"\"Deprecated features the server still provides.\"\"\"\n  deprecatedFeatures: [String!]!\n}\n\n# Custom scalars\n\"\"\"\nCustom scalar for date/time values.\n\"\"\"\nscalar DateTime\n\n\"\"\"\nCustom scalar for JSON data.\n\"\"\"\nscalar JSON\n\n# Pagination Types\n\"\"\"\nConnection interface for cursor-based pagination.\nAll list queries SHOULD use this pattern for consistency.\n\"\"\"\ninterface Connection {\n  \"\"\"Information about the current page.\"\"\"\n  pageInfo: PageInfo!\n\n  \"\"\"Total count of items (optional but recommended).\"\"\"\n  totalCount: Int\n}\n\n\"\"\"\nPage information for cursor-based pagination.\n\"\"\"\ntype PageInfo {\n  \"\"\"Whether there are more items after this page.\"\"\"\n  hasNextPage: Boolean!\n\n  \"\"\"Whether there are more items before this page.\"\"\"\n  hasPreviousPage: Boolean!\n\n  \"\"\"Cursor for the first item in this page.\"\"\"\n  startCursor: String\n\n  \"\"\"Cursor for the last item in this page.\"\"\"\n  endCursor: String\n}\n\n\"\"\"\nEdge wrapper for cursor-based pagination.\n\"\"\"\ninterface Edge {\n  \"\"\"Cursor for this item.\"\"\"\n  cursor: String!\n\n  \"\"\"The item itself.\"\"\"\n  node: Node!\n}\n\n\"\"\"\nArguments for cursor-based pagination.\n\"\"\"\ninput PaginationArgs {\n  \"\"\"Number of items to return.\"\"\"\n  first: Int\n\n  \"\"\"Number of items to return before this cursor.\"\"\"\n  last: Int\n\n  \"\"\"Cursor to start after.\"\"\"\n  after: String\n\n  \"\"\"Cursor to start before.\"\"\"\n  before: String\n}\n\n\"\"\"\nArguments for offset-based pagination (MAY be used as alternative).\n\"\"\"\ninput OffsetPaginationArgs {\n  \"\"\"Number of items to skip.\"\"\"\n  offset: Int = 0\n\n  \"\"\"Number of items to return.\"\"\"\n  limit: Int = 10\n}\n\n# Query naming conventions (SHOULD):\n#   get<EntityType>(id: ID!): <EntityType>\n#     e.g. getUser(id: ID!): User\n#   list<EntityType>s(args: PaginationArgs): <EntityType>Connection\n#     e.g. listUsers(args: PaginationArgs): UserConnection\n#   search<EntityType>s(query: String!, args: PaginationArgs): <EntityType>Connection\n#     e.g. searchUsers(query: String!, args: PaginationArgs): UserConnection\n#\n# Mutation naming conventions (SHOULD):\n#   create<EntityType>(input: Create<EntityType>Input!): Create<EntityType>Cascade!\n#     e.g. createUser(input: CreateUserInput!): CreateUserCascade!\n#   update<EntityType>(id: ID!, input: Update<EntityType>Input!): Update<EntityType>Cascade!\n#     e.g. updateUser(id: ID!, input: UpdateUserInput!): UpdateUserCascade!\n#   delete<EntityType>(id: ID!): Delete<EntityType>Cascade!\n#     e.g. deleteUser(id: ID!): DeleteUserCascade!\n";

export const DOMAIN_SCHEMA: string = "# Conformance domain\n#\n# The schema every server conformance case runs against, merged with\n# reference/cascade_base.graphql. A server under test implements it with the\n# behavior described in conformance-tests/README.md.\n\ntype Query {\n  user(id: ID!): User\n  users: [User!]!\n  post(id: ID!): Post\n  node(id: ID!): Node\n}\n\ntype User implements Node {\n  id: ID!\n  name: String!\n  email: String!\n  manager: User\n  posts: [Post!]!\n  postCount: Int!\n}\n\ntype Post implements Node {\n  id: ID!\n  title: String!\n  published: Boolean!\n  author: User!\n}\n\ninput CreateUserInput {\n  name: String!\n  email: String!\n  managerId: ID\n}\n\ninput UpdateUserInput {\n  name: String\n  email: String\n  managerId: ID\n}\n\ninput CreatePostInput {\n  title: String!\n  authorId: ID!\n}\n\ninput UpdatePostInput {\n  title: String\n  published: Boolean\n}\n\ntype UserCascade implements CascadeResponse {\n  success: Boolean!\n  errors: [CascadeError!]\n  data: User\n  cascade: CascadeUpdates!\n}\n\ntype PostCascade implements CascadeResponse {\n  success: Boolean!\n  errors: [CascadeError!]\n  data: Post\n  cascade: CascadeUpdates!\n}\n\ntype RenameUserPayload implements CascadePayload {\n  data: User!\n  cascade: CascadeUpdates!\n  warnings: [CascadeError!]!\n}\n\nunion RenameUserResult = RenameUserPayload | CascadeFailure\n\ntype Mutation {\n  createUser(input: CreateUserInput!): UserCascade!\n  updateUser(id: ID!, input: UpdateUserInput!): UserCascade!\n  deleteUser(id: ID!): UserCascade!\n  renameUser(id: ID!, name: String!): RenameUserResult!\n  createPost(input: CreatePostInput!): PostCascade!\n  updatePost(id: ID!, input: UpdatePostInput!): PostCascade!\n  publishPosts(authorId: ID!): UserCascade!\n}\n";

